import { execFileSync } from 'node:child_process';
export const EXE = '/workspace/dataset/test19_executable';
export const MK = { a:'MKAA', b:'MKBB', c:'MKCC', d:'MKDD', e:'MKEE', f:'MKFF' };
const ORDER = ['a','b','c','d','e','f'];

// Use --k=value form so values starting with '-' are safe for argparse.
export function runEq(args) {
  const argv = [];
  for (const k of ORDER) argv.push('--' + k + '=' + (args[k] === undefined ? MK[k] : args[k]));
  try { return execFileSync(EXE, argv, { encoding: 'utf8', maxBuffer: 1 << 28 }); }
  catch (e) { return 'ERR(' + e.status + ')\n' + (e.stdout || '') + (e.stderr || ''); }
}

export function phaseA(s) {
  const args = { ...MK }; args.a = s;
  const out = runEq(args);
  if (out.startsWith('ERR(')) return out;
  const lines = out.split('\n');
  const end = lines.indexOf('<p>' + MK.b + '</p>');
  if (end < 0) return 'NOMARKER:' + out;
  return lines.slice(0, end).join('\n');
}

// Batch helper: prints JSON lines {i, in, out}
export function report(cases) {
  for (let i = 0; i < cases.length; i++) {
    const s = cases[i];
    const o = phaseA(s);
    console.log(JSON.stringify(s) + '  =>  ' + JSON.stringify(o));
  }
}

